#include "ember/SfvSelectGrid.hxx"

#include <nlohmann/json.hpp>

#include <algorithm>
#include <cmath>
#include <initializer_list>

namespace sfve::grid {

// Generated by CMakeLists.txt from data/select-grid.json (sfve_ember).
extern const char* const kEmbeddedSelectGridJson;

namespace {

// The most columns and rows a table may name: far past any select screen,
// small enough that a cell's number never overflows.
constexpr int kMostColumns = 256;
constexpr int kMostRows = 256;

// An object whose keys are all among `allowed` and include `required`: a
// hand-made table with a misspelt key is refused rather than read without it.
bool Keys(const nlohmann::json& value, std::initializer_list<const char*> required, std::initializer_list<const char*> allowed)
{
	if (!value.is_object()) return false;
	for (const char* key : required) {
		if (!value.contains(key)) return false;
	}
	for (auto item = value.begin(); item != value.end(); ++item) {
		if (std::none_of(allowed.begin(), allowed.end(), [&item](const char* key) { return item.key() == key; })) return false;
	}
	return true;
}

// A whole number from `least` to `most`.
bool Whole(const nlohmann::json& value, long long least, long long most)
{
	if (!value.is_number_integer()) return false;
	// The parser keeps a number without a sign as unsigned.
	if (value.is_number_unsigned()) {
		const unsigned long long number = value.get<unsigned long long>();
		return number <= (unsigned long long)most && (long long)number >= least;
	}
	const long long number = value.get<long long>();
	return number >= least && number <= most;
}

// A cell's {"column", "row"} on a grid of `columns`.
bool ReadCell(const nlohmann::json& value, int columns, Cell& cell)
{
	if (!Keys(value, {"column", "row"}, {"code", "column", "row"}) || !Whole(value["column"], 0, columns - 1) ||
		!Whole(value["row"], 0, kMostRows - 1)) {
		return false;
	}
	cell.column = value["column"].get<int>();
	cell.row = value["row"].get<int>();
	return true;
}

std::string CellText(Cell cell)
{
	return "column " + std::to_string(cell.column) + ", row " + std::to_string(cell.row);
}

// The cells in row order (left to right, then the next row): a cell's place.
long long Order(const SelectGrid& grid, Cell cell)
{
	return (long long)cell.row * grid.columns + cell.column;
}

} // namespace

bool ParseSelectGrid(std::string_view json, SelectGrid& grid, std::string& error)
{
	SelectGrid parsed;
	try {
		const nlohmann::json root = nlohmann::json::parse(json.begin(), json.end());
		if (!Keys(root, {"columns", "fighters"}, {"columns", "rowOffsets", "fighters", "random"})) {
			error = "not a select grid: an object of columns, fighters and optionally rowOffsets and random";
			return false;
		}
		if (!Whole(root["columns"], 1, kMostColumns)) {
			error = "columns is not a whole number from 1 to " + std::to_string(kMostColumns);
			return false;
		}
		parsed.columns = root["columns"].get<int>();
		if (root.contains("rowOffsets")) {
			const nlohmann::json& offsets = root["rowOffsets"];
			if (!offsets.is_array() || offsets.size() > (size_t)kMostRows) {
				error = "rowOffsets is not a list of numbers, one per row";
				return false;
			}
			for (const nlohmann::json& offset : offsets) {
				if (!offset.is_number() || !std::isfinite(offset.get<double>())) {
					error = "a row offset is not a number";
					return false;
				}
				parsed.rowOffsets.push_back(offset.get<float>());
			}
		}
		const nlohmann::json& fighters = root["fighters"];
		if (!fighters.is_array()) {
			error = "fighters is not a list";
			return false;
		}
		// Each cell holds one entry, and each code has one cell.
		const auto taken = [&parsed](Cell cell) {
			return (parsed.random && *parsed.random == cell) ||
				std::any_of(parsed.fighters.begin(), parsed.fighters.end(), [cell](const Entry& entry) { return entry.cell == cell; });
		};
		if (root.contains("random")) {
			Cell cell;
			if (!Keys(root["random"], {"column", "row"}, {"column", "row"}) || !ReadCell(root["random"], parsed.columns, cell)) {
				error = "random is not a cell of the grid";
				return false;
			}
			parsed.random = cell;
		}
		for (const nlohmann::json& fighter : fighters) {
			Entry entry;
			if (!Keys(fighter, {"code", "column", "row"}, {"code", "column", "row"}) || !fighter["code"].is_string() ||
				fighter["code"].get<std::string>().empty() || !ReadCell(fighter, parsed.columns, entry.cell)) {
				error = "a fighter is not a code and a cell of the grid (fighter " + std::to_string(parsed.fighters.size() + 1) + ")";
				return false;
			}
			entry.code = fighter["code"].get<std::string>();
			if (CellOf(parsed, entry.code)) {
				error = entry.code + " has two cells";
				return false;
			}
			if (taken(entry.cell)) {
				error = entry.code + "'s cell (" + CellText(entry.cell) + ") is taken";
				return false;
			}
			parsed.fighters.push_back(std::move(entry));
		}
	} catch (const nlohmann::json::exception& e) {
		error = std::string("not JSON: ") + e.what();
		return false;
	}
	grid = std::move(parsed);
	error.clear();
	return true;
}

const SelectGrid& EmbeddedSelectGrid()
{
	static const SelectGrid grid = [] {
		SelectGrid parsed;
		std::string error;
		if (!ParseSelectGrid(kEmbeddedSelectGridJson, parsed, error)) parsed = {};
		return parsed;
	}();
	return grid;
}

std::optional<Cell> CellOf(const SelectGrid& grid, std::string_view code)
{
	const auto entry =
		std::find_if(grid.fighters.begin(), grid.fighters.end(), [code](const Entry& candidate) { return candidate.code == code; });
	if (entry == grid.fighters.end()) return std::nullopt;
	return entry->cell;
}

std::optional<std::string> CodeAt(const SelectGrid& grid, Cell cell)
{
	if (grid.random && *grid.random == cell) return std::string(kRandomCellCode);
	const auto entry =
		std::find_if(grid.fighters.begin(), grid.fighters.end(), [cell](const Entry& candidate) { return candidate.cell == cell; });
	if (entry == grid.fighters.end()) return std::nullopt;
	return entry->code;
}

int RowCount(const SelectGrid& grid)
{
	int rows = grid.random ? grid.random->row + 1 : 0;
	for (const Entry& entry : grid.fighters) rows = (std::max)(rows, entry.cell.row + 1);
	return rows;
}

float RowOffset(const SelectGrid& grid, int row)
{
	return row >= 0 && row < (int)grid.rowOffsets.size() ? grid.rowOffsets[(size_t)row] : 0.f;
}

std::vector<std::string> FitToRoster(SelectGrid& grid, const std::vector<std::string>& roster)
{
	std::vector<std::string> added;
	if (grid.columns <= 0) return added;
	// The first cell after the last one taken, in row order.
	long long next = 0;
	if (grid.random) next = Order(grid, *grid.random) + 1;
	for (const Entry& entry : grid.fighters) next = (std::max)(next, Order(grid, entry.cell) + 1);
	for (const std::string& code : roster) {
		if (code.empty() || CellOf(grid, code)) continue;
		const Cell cell{(int)(next % grid.columns), (int)(next / grid.columns)};
		grid.fighters.push_back({code, cell});
		added.push_back(code);
		next++;
	}
	return added;
}

} // namespace sfve::grid
